repo_root <- normalizePath(file.path(testthat::test_path(), "..", "..", ".."), winslash = "/", mustWork = TRUE)
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_intraday_momentum_engine.R"))
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_reg_01_2_strategy_overlay.R"))
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_reg_09_1_robust_slope_fit_poc.R"))
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_reg_11_1_causal_change_point_poc.R"))

hreg111_test_bars <- function(n = 180L) { dates <- seq(as.Date("2020-01-02"), by = "day", length.out = n); close <- exp(cumsum(c(rep(0, 60), rep(.012, n - 60)) + sin(seq_len(n)) * .001)); data.frame(symbol = "TEST", session_date = dates, timestamp_utc = as.POSIXct(dates, tz = "UTC"), open = close, high = close * 1.01, low = close * .99, close = close, volume = 1000) }

testthat::test_that("contract freezes one positive causal onset lane", { x <- hreg111_contract(); testthat::expect_equal(x$hypothesis_id, "HYP-REG-11.1"); testthat::expect_equal(x$volatility_window, 20L); testthat::expect_equal(x$reference_k, .10); testthat::expect_equal(x$eligibility_sessions, 10L); testthat::expect_equal(x$confirmation_start, as.Date("2024-01-02")) })
testthat::test_that("standardization uses prior returns and clips extremes", { z <- hreg111_standardize_returns(c(rep(1, 20) + seq_len(20) * .01, 100), 20, 3); testthat::expect_true(all(is.na(z[1:20]))); testthat::expect_equal(z[[21]], 3) })
testthat::test_that("one positive jump cannot trigger a threshold above the clip", { c <- hreg111_contract(); z <- c(rep(0, 30), 3, rep(0, 30)); x <- hreg111_cusum_stream(z, 4, c); testthat::expect_false(any(x$positive_alarm)) })
testthat::test_that("persistent positive evidence alarms and creates exactly ten eligible sessions", { c <- hreg111_contract(); z <- c(rep(0, 25), rep(.8, 40)); x <- hreg111_cusum_stream(z, 3, c); a <- which(x$positive_alarm)[1L]; testthat::expect_true(is.finite(a)); testthat::expect_equal(which(x$recent_positive_onset_eligible)[1:10], a:(a + 9L)); testthat::expect_false(x$recent_positive_onset_eligible[[a + 10L]]) })
testthat::test_that("refractory period prevents window extension", { c <- hreg111_contract(); z <- rep(1, 20); x <- hreg111_cusum_stream(z, 2, c); a <- which(x$positive_alarm); testthat::expect_equal(length(a), 2L); testthat::expect_gte(diff(a), c$refractory_sessions) })
testthat::test_that("price scale does not change the ledger", { c <- hreg111_contract(); bars <- hreg111_test_bars(); a <- hreg111_build_asset_ledger(bars, 4, c); bars$open <- bars$open * 7; bars$high <- bars$high * 7; bars$low <- bars$low * 7; bars$close <- bars$close * 7; b <- hreg111_build_asset_ledger(bars, 4, c); testthat::expect_equal(a$trailing_standardized_return, b$trailing_standardized_return, tolerance = 1e-12); testthat::expect_equal(a$positive_alarm, b$positive_alarm) })
testthat::test_that("append audit is exactly causal", { testthat::expect_true(all(hreg111_causality_audit(4)$passed)) })
testthat::test_that("confirmation and duplicate rows are rejected", { bars <- hreg111_test_bars(); bars$session_date <- seq(as.Date("2023-11-01"), by = "day", length.out = nrow(bars)); testthat::expect_error(hreg91_assert_bars(bars, hreg111_contract()), "Confirmation"); bars <- hreg111_test_bars(); testthat::expect_error(hreg91_assert_bars(rbind(bars, bars[1, ]), hreg111_contract()), "duplicated") })
testthat::test_that("entry policy skips rejected crosses rather than deferring", { bars <- hreg111_test_bars(); frame <- hreg111_align(hreg12_cross_frame(bars), hreg111_build_asset_ledger(bars, 4)); cross <- which(frame$cross_up)[1L]; frame$recent_positive_onset_eligible[] <- FALSE; schedule <- hreg111_schedule(frame, min(frame$session_date), max(frame$session_date), "ENTRY_RECENT_POSITIVE_ONSET_ONLY"); testthat::expect_true(schedule$blocked_entry[[cross + 1L]]); testthat::expect_false(schedule$target[[cross + 1L]]); testthat::expect_false(any(schedule$entry_signal[seq.int(cross + 2L, min(cross + 4L, nrow(schedule)))])) })
testthat::test_that("unfiltered and fully eligible schedules agree", { bars <- hreg111_test_bars(); frame <- hreg111_align(hreg12_cross_frame(bars), hreg111_build_asset_ledger(bars, 4)); a <- hreg111_schedule(frame, min(frame$session_date), max(frame$session_date), "UNFILTERED"); frame$recent_positive_onset_eligible[] <- TRUE; b <- hreg111_schedule(frame, min(frame$session_date), max(frame$session_date), "ENTRY_RECENT_POSITIVE_ONSET_ONLY"); testthat::expect_equal(a$target, b$target) })
testthat::test_that("circular controls are deterministic and nonzero", { bars <- hreg111_test_bars(); frame <- hreg111_align(hreg12_cross_frame(bars), hreg111_build_asset_ledger(bars, 2)); a <- hreg111_shifted_schedule(frame, min(frame$session_date), max(frame$session_date), 7); b <- hreg111_shifted_schedule(frame, min(frame$session_date), max(frame$session_date), 7); testthat::expect_equal(a$target, b$target); testthat::expect_gt(attr(a, "shift_offset"), 0) })
testthat::test_that("exposure-nearest selection ignores returns", { x <- data.frame(simulation_id = 1:4, median_exposure = c(.1, .2, .3, .4), median_return = c(100, -100, 50, 0)); testthat::expect_equal(hreg111_exposure_near_ids(x, .26, 2), c(3L, 2L)) })
